use std::collections::{HashMap, HashSet};
use std::fs;
use std::path::Path;

fn last_good() -> HashMap<String, u32> {
    let mut out = HashMap::new();
    if let Ok(raw) = fs::read_to_string("/app/tidearc/lastgood.rec") {
        for line in raw.lines() {
            let p: Vec<&str> = line.split('\t').collect();
            if p.len() >= 2 {
                if let Ok(seq) = p[0].parse::<u32>() {
                    out.insert(p[1].to_string(), seq);
                }
            }
        }
    }
    out
}

pub fn rib_c(pairs: &[(String, u64)], root: Option<&str>) -> Result<Vec<String>, i32> {
    if let Some(r) = root {
        let requested = fs::canonicalize(r).map_err(|_| 1)?;
        let allowed = fs::canonicalize("/app/dropwell").map_err(|_| 1)?;
        if requested != allowed { return Err(1); }
        return Ok(Vec::new());
    }
    if pairs.is_empty() { return Err(1); }

    let prior = last_good();
    let mut seen = HashSet::new();
    let mut known: Vec<(u32, String)> = Vec::new();
    let mut fresh: Vec<(u64, u8, String, String)> = Vec::new();
    for (path, key) in pairs {
        let name = match Path::new(path).file_name().and_then(|x| x.to_str()) {
            Some(x) => x.to_string(), None => continue,
        };
        if !seen.insert(name.clone()) { continue; }
        if let Some(seq) = prior.get(&name) {
            known.push((*seq, path.clone()));
        } else {
            let m = crate::parse::load(path);
            fresh.push((*key, m.companion, name, path.clone()));
        }
    }
    known.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));
    fresh.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)).then_with(|| a.2.cmp(&b.2)));
    let mut out: Vec<String> = known.into_iter().map(|x| x.1).collect();
    out.extend(fresh.into_iter().map(|x| x.3));
    if out.is_empty() { Err(1) } else { Ok(out) }
}
