pub fn pour() -> i32 {
    let root = std::env::args().nth(2).unwrap_or_else(|| "/app/dropwell".to_string());
    if let Err(c) = crate::fold::rib_c(&[], Some(&root)) { mark_false(); return c; }
    let well = match crate::walk::rib_a() { Ok(v) if !v.is_empty() => v, _ => { mark_false(); return 1 } };
    let well_names: std::collections::HashSet<String> = well.iter().filter_map(|p| Path::new(p).file_name()?.to_str().map(str::to_string)).collect();
