    let mut seen = std::collections::HashSet::new();
    for line in ribbon.lines() {
        let p: Vec<&str> = line.split('\t').collect();
        if p.len() != 3 { continue; }
        let seq: u32 = match p[0].parse() { Ok(x) => x, Err(_) => continue };
        let full = p[1];
        let name = match Path::new(full).file_name().and_then(|x| x.to_str()) { Some(x) => x.to_string(), None => continue };
